export class EmployeId {
  value: string;

  constructor(value: string) {
    this.value = value;
    this.ensureIsValid();
  }

  // employee.id es bigint GENERATED BY DEFAULT AS IDENTITY: un entero positivo.
  private ensureIsValid() {
    if (!/^[0-9]+$/.test(this.value)) {
      throw new Error("EmployeId must be a positive integer (employee.id is bigint)");
    }
  }
}
